  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "MirrorLedger",
  "type": "object",
  "required": [
    "ledger_id", "created_at", "authority", "version",
    "D0_raw", "D1_normalized", "D2_derived", "D3_reconstructed", "D4_interpreted",
    "residue", "contested", "solvency", "audit_log"
  ],
  "properties": {
    "ledger_id": { "type": "string" },
