## 3. Python Skeleton (Core Classes)

```python
from dataclasses import dataclass, field
from typing import Any, List, Dict, Optional, Literal
from datetime import datetime
import hashlib
import json

ClassType = Literal["observed", "partial", "misused", "missing"]
SolvencyStatus = Literal["SAFE", "INSOLVENT"]

@dataclass
class Quality:
    completeness: float = 1.0
    provenance_strength: float = 1.0
    reproducibility: float = 1.0
    temporal_precision: float = 1.0
    contextual_validity: float = 1.0

    def weight(self) -> float:
        return (self.completeness * self.provenance_strength *
                self.reproducibility * self.temporal_precision *
                self.contextual_validity)

@dataclass
class Datum:
    id: str
    value: Any
    class_: ClassType
    source: str
    unit: Optional[str] = None
    time: Optional[str] = None
    location: Optional[str] = None
    method: Optional[str] = None
    transformations: List[str] = field(default_factory=list)
    uncertainty: Any = None
    quality: Quality = field(default_factory=Quality)

    @property
    def support_weight(self) -> float:
        return self.quality.weight()

@dataclass
class Solvency:
    status: SolvencyStatus
    claimed: float
    interior: float
    guard: float = 1e-12

    def check(self) -> bool:
        return self.claimed <= self.interior + self.guard

@dataclass
class MirrorLedger:
    ledger_id: str
    authority: str
    version: str = "0.1"
    created_at: str = field(default_factory=lambda: datetime.utcnow().isoformat() + "Z")

    D0_raw: List[Datum] = field(default_factory=list)
    D1_normalized: List[Datum] = field(default_factory=list)
    D2_derived: List[Datum] = field(default_factory=list)
    D3_reconstructed: List[Datum] = field(default_factory=list)
    D4_interpreted: List[Datum] = field(default_factory=list)

    residue: Optional[Dict] = None
    contested: Optional[Dict] = None
    solvency: Optional[Solvency] = None
    mirror_run: Optional[Dict] = None
    audit_log: List[Dict] = field(default_factory=list)

    def append_audit(self, operation: str, notes: str = ""):
        entry = {
            "timestamp": datetime.utcnow().isoformat() + "Z",
            "operation": operation,
            "hash": self._content_hash(),
            "notes": notes
        }
        self.audit_log.append(entry)

    def _content_hash(self) -> str:
        payload = json.dumps({
            "D0": [d.id for d in self.D0_raw],
            "D1": [d.id for d in self.D1_normalized],
            "D2": [d.id for d in self.D2_derived],
            "D3": [d.id for d in self.D3_reconstructed],
            "D4": [d.id for d in self.D4_interpreted],
        }, sort_keys=True)
        return hashlib.sha256(payload.encode()).hexdigest()[:16]

    def run_solvency_gate(self, claimed: float, interior: float) -> Solvency:
        sol = Solvency(
            status="SAFE" if claimed <= interior + 1e-12 else "INSOLVENT",
            claimed=claimed,
            interior=interior
        )
        self.solvency = sol
        self.append_audit("solvency_gate", f"status={sol.status}")
        return sol
```

