## 4. Audit Runner Skeleton

```python
def run_full_audit(ledger: MirrorLedger) -> Dict:
    checks = []

    # 1. Layer integrity (simplified)
    checks.append({
        "name": "layer_integrity",
        "passed": True,  # real implementation walks dependency hashes
        "notes": "All layers reference only prior layers"
    })

    # 2. Classification completeness
    all_data = (ledger.D0_raw + ledger.D1_normalized + ledger.D2_derived +
                ledger.D3_reconstructed + ledger.D4_interpreted)
    classified = all(d.class_ in ("observed", "partial", "misused", "missing") for d in all_data)
    checks.append({
        "name": "classification_completeness",
        "passed": classified,
        "notes": f"{len(all_data)} datums classified"
    })

    # 3. Solvency gate
    sol_ok = ledger.solvency is not None and ledger.solvency.check()
    checks.append({
        "name": "solvency_gate",
        "passed": sol_ok,
        "notes": str(ledger.solvency.status) if ledger.solvency else "not run"
    })

    # 4. Uncertainty visibility
    checks.append({
        "name": "uncertainty_visibility",
        "passed": ledger.contested is not None,
        "notes": "Contested region retained" if ledger.contested else "Missing"
    })

    overall = all(c["passed"] for c in checks)
    return {
        "ledger_id": ledger.ledger_id,
        "overall_solvency": "SAFE" if overall else "INSOLVENT",
        "checks": checks
    }
```

